@namespace sv_3d4ef6fd08ca4fc593c8ec8499b5f894.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn-remove" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" value="@Entry.Company" @onchange="e => Update(company: (string?)e.Value)" required />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" value="@Entry.Title" @onchange="e => Update(title: (string?)e.Value)" required />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" value="@Entry.StartDate.ToString("yyyy-MM-dd")" @onchange="e => Update(startDate: DateTime.Parse((string)e.Value!))" required />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@Entry.EndDate?.ToString("yyyy-MM-dd")" @onchange="e => Update(endDate: string.IsNullOrEmpty((string?)e.Value) ? null : DateTime.Parse((string)e.Value!))" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="HandleCurrentToggle" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea rows="3" value="@Entry.Description" @onchange="e => Update(description: (string?)e.Value)"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntryModel Entry { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryModel> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.IsCurrent;

    private async Task Update(string? company = null, string? title = null, DateTime? startDate = null, DateTime? endDate = null, string? description = null, bool? isCurrent = null)
    {
        var updated = Entry with
        {
            Company = company ?? Entry.Company,
            Title = title ?? Entry.Title,
            StartDate = startDate ?? Entry.StartDate,
            EndDate = isCurrent == true ? null : (endDate ?? Entry.EndDate),
            Description = description ?? Entry.Description,
            IsCurrent = isCurrent ?? Entry.IsCurrent
        };
        await OnChanged.InvokeAsync(updated);
    }

    private async Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var current = (bool)e.Value!;
        await Update(isCurrent: current, endDate: current ? null : Entry.EndDate);
    }
}

