@namespace sv_3d4ef6fd08ca4fc593c8ec8499b5f894.Components.Pages.Apply

<div class="step-content">
    <h2>Personal Information</h2>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="error-message">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" @bind="Model.FullName" placeholder="Enter your full name" />
    </div>

    <div class="form-group">
        <label>Email Address *</label>
        <input type="email" @bind="Model.Email" placeholder="you@example.com" />
    </div>

    <div class="form-group">
        <label>Phone Number *</label>
        <input type="tel" @bind="Model.Phone" placeholder="(555) 123-4567" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" @bind="Model.Address" placeholder="Enter your address"></textarea>
    </div>

    <div class="step-actions">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName))
        {
            ErrorMessage = "Full name is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            ErrorMessage = "Email is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            ErrorMessage = "Phone number is required.";
            return;
        }
        if (string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "Address is required.";
            return;
        }

        IsValidating = true;
        try
        {
            var emailValid = await ValidateEmail(Model.Email);
            if (!emailValid)
            {
                ErrorMessage = "The email address is not valid. Please check and try again.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        await OnNext.InvokeAsync();
    }
}

